contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that for any non-empty _tos array and any inputs, c.transfer returns true (doesn't revert)
    // and that the call does not change address(this).balance (C.transfer is not payable to this contract).
    function run(address from, address caddress, address[] memory _tos, uint v, uint sendAmount) public payable {
        require(_tos.length > 0);
        // ensure we have enough balance if we attempt to send Ether when calling c (we won't send Ether to c.transfer)
        require(address(this).balance >= sendAmount);

        bool reverted;
        bool ret;
        // call transfer and capture revert status and return value
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // The general rule: when provided a non-empty _tos, the call must not revert and must return true;
        // additionally, the call should not change this contract's balance (we didn't send Ether to c in the call).
        assert(reverted == false && ret == true && address(this).balance >= sendAmount);
    }

    receive() external payable {}
}

